#include <cstdint>
#include <format>
#include <functional>
#include <iostream>
#include <memory>
#include <utility>
#include <vector>

// Stands in for the executor: it keeps callbacks and runs them later, which is what a
// subscription and a timer do.
class Loop {
 public:
  void add(std::function<void()> callback) { callbacks_.push_back(std::move(callback)); }
  void spin_once() const {
    for (const std::function<void()>& callback : callbacks_) callback();
  }

 private:
  std::vector<std::function<void()>> callbacks_;
};

// The plain class the node keeps its logic in.
class Tally {
 public:
  void add() { ++count_; }
  [[nodiscard]] std::int64_t count() const { return count_; }

 private:
  std::int64_t count_ = 0;
};

int main() {
  Loop loop;
  auto tally = std::make_unique<Tally>();
  Tally* borrowed = tally.get();  // the raw pointer the lambda captures
  loop.add([borrowed] {
    borrowed->add();
    std::cout << std::format("count {}\n", borrowed->count());
  });

  loop.spin_once();  // fine, the tally is alive
  tally.reset();     // the node let it go; the loop still holds the callback
  loop.spin_once();  // reads an object that is gone
}

