class Tally {
 public:
  void add() { ++count_; }
  [[nodiscard]] std::int64_t count() const { return count_; }

 private:
  std::int64_t count_ = 0;
};

int main() {
  Loop loop;
  auto tally = std::make_shared<Tally>();
  // The callback holds a weak reference, so it can ask whether the object is still there.
  loop.add([watched = std::weak_ptr<Tally>(tally)] {
    const std::shared_ptr<Tally> alive = watched.lock();
    if (!alive) {
      std::cout << "the tally is gone, nothing to do\n";
      return;
    }
    alive->add();
    std::cout << std::format("count {}\n", alive->count());
  });

  loop.spin_once();
  tally.reset();
  loop.spin_once();
}

