#include <example_interfaces/srv/trigger.hpp>
#include <nav_msgs/msg/odometry.hpp>
#include <rclcpp/rclcpp.hpp>

using namespace std::chrono_literals;

// How late the timer has been. No ROS types and no clock: both times arrive as arguments, so a
// test replays any timeline in a few microseconds.
class Lateness {
 public:
  void record(std::int64_t expected_ns, std::int64_t actual_ns) {
    const std::int64_t late_ns = actual_ns - expected_ns;
    worst_ns_ = worst_ns_ ? std::max(*worst_ns_, late_ns) : late_ns;
    ++calls_;
  }

  [[nodiscard]] std::optional<std::int64_t> worst() const { return worst_ns_; }
  [[nodiscard]] std::int64_t calls() const { return calls_; }
  void forget() { *this = Lateness{}; }

 private:
  std::optional<std::int64_t> worst_ns_;
  std::int64_t calls_ = 0;
};

class Watchdog : public rclcpp::Node {
 public:
  using Trigger = example_interfaces::srv::Trigger;

  explicit Watchdog(const rclcpp::NodeOptions& options = rclcpp::NodeOptions()) : Node("watchdog", options) {
    // All three entities stay in the node's default callback group, which is mutually exclusive,
    // because all three touch `lateness_` and `messages_`. Splitting them would need a lock.
    odometry_ = create_subscription<nav_msgs::msg::Odometry>(
        "odom", rclcpp::QoS(rclcpp::KeepLast(10)),
        [this](const nav_msgs::msg::Odometry&) { ++messages_; });

    // The callback takes the two times rclcpp already knows, so the node needs no clock here.
    timer_ = create_timer(100ms, [this](const rclcpp::TimerInfo& info) { on_tick(info); });

    service_ = create_service<Trigger>(
        "~/release", [this](const std::shared_ptr<Trigger::Request>, std::shared_ptr<Trigger::Response> response) {
          response->message = report();
          response->success = true;
          lateness_.forget();  // resets the contents; the object itself is never released
        });
  }

 private:
  void on_tick(const rclcpp::TimerInfo& info) {
    lateness_.record(info.expected_call_time.nanoseconds(), info.actual_call_time.nanoseconds());
    if (const std::optional<std::int64_t> worst = lateness_.worst(); worst && *worst > 50'000'000) {
      RCLCPP_WARN(get_logger(), "timer was %" PRId64 " ms late within %" PRId64 " calls", *worst / 1'000'000,
                  lateness_.calls());
    }
  }

  [[nodiscard]] std::string report() const {
    const std::optional<std::int64_t> worst = lateness_.worst();
    return std::format("{} odometry messages, worst lateness {} us", messages_,
                       worst ? *worst / 1000 : 0);
  }

  Lateness lateness_;        // declared first, so it is destroyed last
  std::int64_t messages_ = 0;
  rclcpp::Subscription<nav_msgs::msg::Odometry>::SharedPtr odometry_;
  rclcpp::TimerBase::SharedPtr timer_;
  rclcpp::Service<Trigger>::SharedPtr service_;
};

int main(int argc, char** argv) {
  rclcpp::init(argc, argv);
  rclcpp::executors::MultiThreadedExecutor executor;
  const auto node = std::make_shared<Watchdog>();
  executor.add_node(node);
  executor.spin();
  rclcpp::shutdown();
}
